function ortaArifmetik(a, b) {
  return (a + b) / 2;
}
console.log(ortaArifmetik(10, 20));

function repeatStr(s, n) {
  let out = "";
  for (let i = 0; i < n; i++) out += s;
  return out;
}
console.log(repeatStr("ha", 3));

function clamp(n, min, max) {
  if (n < min) return min;
  if (n > max) return max;
  return n;
}
console.log(clamp(15, 0, 10));

function applyTwice(fn, x) {
  return fn(fn(x));
}
console.log(applyTwice((n) => n + 1, 3));

function sumRange(from, to) {
  let s = 0;
  for (let i = from; i <= to; i++) s += i;
  return s;
}
console.log(sumRange(1, 4));
